import React, { useMemo, useState } from "react";
import {
  Activity, AlertTriangle, ArrowUpRight, BarChart3, Bell, CalendarDays,
  Check, CheckCircle2, ChevronRight, Clock3, Database, FlaskConical,
  Gauge, HardDrive, LayoutDashboard, LockKeyhole, LogOut, Menu, Microscope,
  Network, PackageCheck, Radio, RefreshCw, Search, Settings2, ShieldCheck,
  SlidersHorizontal, Timer, UserRound, Users, Wrench, X, XCircle
} from "lucide-react";

type RoleId = "researcher" | "technician" | "manager" | "institution" | "system";
type TabId = "overview" | "availability" | "bookings" | "waitlist" | "operations" | "sharing" | "analytics" | "system";
type Instrument = { name: string; type: string; site: string; status: string; detail: string; util: number; idle: string; demand: number };

const roles: { id: RoleId; label: string; short: string; description: string; icon: typeof Microscope; color: string }[] = [
  { id: "researcher", label: "Researcher / Student", short: "Researcher", description: "Find an open instrument, request time, and track your queue.", icon: Microscope, color: "#a8d5ba" },
  { id: "technician", label: "Lab Technician", short: "Technician", description: "Keep instrument status accurate and maintenance moving.", icon: Wrench, color: "#e7bf78" },
  { id: "manager", label: "Lab Manager / Department Head", short: "Lab Manager", description: "Own utilization, approvals, sharing, and demand decisions.", icon: Gauge, color: "#8bb7d9" },
  { id: "institution", label: "Institution Administrator", short: "Institution Admin", description: "See organization-wide performance and partner access.", icon: Network, color: "#c8a5d9" },
  { id: "system", label: "System Admin", short: "System Admin", description: "Maintain configuration, access coverage, and system health.", icon: ShieldCheck, color: "#e29884" },
];

const instruments = [
  { name: "TEM-2200 Electron Microscope", type: "Electron Microscope", site: "Riverside Institute of Technology", status: "Available", detail: "Ready for reservation", util: 84, idle: "—", demand: 18 },
  { name: "Ultra Centrifuge X9", type: "Centrifuge", site: "Riverside Institute of Technology", status: "In Use", detail: "Run ends in 42 min", util: 72, idle: "—", demand: 15 },
  { name: "Mass Spectrometer M-4", type: "Spectrometer", site: "Riverside Institute of Technology", status: "Booked", detail: "Next opening today, 18:30", util: 91, idle: "—", demand: 22 },
  { name: "SEM-500 Scanning Microscope", type: "Electron Microscope", site: "Northfield University", status: "Available", detail: "Partner access enabled", util: 38, idle: "4h 12m", demand: 11 },
  { name: "Beckman Coulter Centrifuge", type: "Centrifuge", site: "Coastal Research Center", status: "Maintenance", detail: "Vacuum seal inspection", util: 27, idle: "2d", demand: 9 },
  { name: "Real-Time PCR System", type: "Thermal Cycler", site: "Summit Polytechnic", status: "Available", detail: "Partner access enabled", util: 46, idle: "5h 06m", demand: 14 },
];

const initialRequests = [
  { id: 1, person: "Priya Nair", institution: "Riverside Institute of Technology", instrument: "TEM-2200 Electron Microscope", window: "Today · 14:00–16:00", status: "Pending" },
  { id: 2, person: "Mateo Ruiz", institution: "Northfield University", instrument: "Mass Spectrometer M-4", window: "Tomorrow · 09:30–11:00", status: "Pending" },
  { id: 3, person: "Amina Okafor", institution: "Coastal Research Center", instrument: "Ultra Centrifuge X9", window: "Fri · 16:00–18:00", status: "Approved" },
];

const tabsFor: Record<RoleId, { id: TabId; label: string; icon: typeof LayoutDashboard }[]> = {
  researcher: [
    { id: "overview", label: "My workspace", icon: LayoutDashboard }, { id: "availability", label: "Find equipment", icon: Search },
    { id: "bookings", label: "My bookings", icon: CalendarDays }, { id: "waitlist", label: "My waitlist", icon: Timer },
  ],
  technician: [
    { id: "overview", label: "Operations", icon: LayoutDashboard }, { id: "operations", label: "Live equipment", icon: Activity },
  ],
  manager: [
    { id: "overview", label: "Manager overview", icon: LayoutDashboard }, { id: "operations", label: "Live status", icon: Activity },
    { id: "analytics", label: "Utilization & demand", icon: BarChart3 }, { id: "sharing", label: "Sharing & approvals", icon: Network },
    { id: "bookings", label: "Booking approvals", icon: CalendarDays }, { id: "waitlist", label: "Optimization", icon: Timer },
  ],
  institution: [
    { id: "overview", label: "Institution overview", icon: LayoutDashboard }, { id: "analytics", label: "Organization analytics", icon: BarChart3 },
    { id: "sharing", label: "Partner network", icon: Network },
  ],
  system: [
    { id: "overview", label: "System overview", icon: LayoutDashboard }, { id: "system", label: "Configuration & audit", icon: Settings2 },
  ],
};

const toneFor = (status: string) => status === "Available" || status === "Approved" ? "green" : status === "In Use" || status === "Pending" ? "amber" : status === "Maintenance" || status === "Rejected" ? "red" : "blue";

function StatusChip({ status }: { status: string }) {
  const tone = toneFor(status);
  return <span className={`chip chip-${tone}`}><span className="chip-dot" />{status}</span>;
}

function Metric({ label, value, hint, accent = "mint" }: { label: string; value: string; hint: string; accent?: string }) {
  return <div className="metric-card">
    <div className="metric-label">{label}<span className={`metric-mark mark-${accent}`} /></div>
    <div className="metric-value">{value}</div><div className="metric-hint">{hint}</div>
  </div>;
}

function Panel({ title, eyebrow, action, children, className = "" }: { title: string; eyebrow?: string; action?: React.ReactNode; children: React.ReactNode; className?: string }) {
  return <section className={`panel ${className}`}><div className="panel-head"><div><div className="eyebrow">{eyebrow}</div><h2>{title}</h2></div>{action}</div>{children}</section>;
}

export function RoleBasedDashboard() {
  const [signedIn, setSignedIn] = useState(false);
  const [role, setRole] = useState<RoleId>("manager");
  const [selectedRole, setSelectedRole] = useState<RoleId>("manager");
  const [tab, setTab] = useState<TabId>("overview");
  const [requests, setRequests] = useState(initialRequests);
  const [waitlisted, setWaitlisted] = useState<string[]>([]);
  const [conflict, setConflict] = useState(false);
  const [notice, setNotice] = useState("Live network synced 18 seconds ago");
  const [query, setQuery] = useState("");

  const activeRole = roles.find((item) => item.id === role)!;
  const RoleIcon = activeRole.icon;
  const tabs = tabsFor[role];
  const filteredInstruments = useMemo(() => instruments.filter((item) => item.name.toLowerCase().includes(query.toLowerCase()) || item.type.toLowerCase().includes(query.toLowerCase())), [query]);

  function signIn() { setRole(selectedRole); setTab("overview"); setSignedIn(true); setNotice("Session opened · permissions scoped to your role"); }
  function switchRole(next: RoleId) { setRole(next); setSelectedRole(next); setTab("overview"); setNotice(`Viewing ${roles.find((item) => item.id === next)?.label} workspace`); }
  function decide(id: number, status: "Approved" | "Rejected") { setRequests((current) => current.map((item) => item.id === id ? { ...item, status } : item)); setNotice(`Request ${status.toLowerCase()} · audit event recorded`); }
  function requestBooking(instrument: string) {
    if (instrument === "TEM-2200 Electron Microscope") { setConflict(true); setNotice("Conflict prevented · that window overlaps an approved reservation"); return; }
    setNotice(`Booking request submitted for ${instrument}`);
  }

  if (!signedIn) return <div className="shell login-shell"><style>{css}</style><div className="login-orbit orbit-a" /><div className="login-orbit orbit-b" />
    <main className="login-layout">
      <div className="login-intro"><div className="brand"><span className="brand-icon"><Radio size={19} /></span><span>LABRESOURCE <b>NETWORK</b></span></div>
        <div className="intro-kicker">Research instrumentation, in focus.</div><h1>Make the next<br /><em>good decision.</em></h1>
        <p>A shared operations room for university labs and their partners. The right view for the people who own the work.</p>
        <div className="trust-row"><span><ShieldCheck size={15} /> Scoped access</span><span><Activity size={15} /> Live signals</span></div>
      </div>
      <div className="login-card"><div className="eyebrow">SECURE SIGN IN</div><h2>Choose your workspace</h2><p className="muted">Your role determines the decisions and resources visible here.</p>
        <div className="role-grid">{roles.map((item) => { const Icon = item.icon; const active = selectedRole === item.id; return <button key={item.id} className={`role-option ${active ? "role-selected" : ""}`} onClick={() => setSelectedRole(item.id)}><span className="role-option-icon" style={{ color: item.color }}><Icon size={18} /></span><span><b>{item.label}</b><small>{item.description}</small></span><ChevronRight size={15} className="role-chevron" /></button>; })}</div>
        <label className="field-label">Institution</label><select className="input"><option>Riverside Institute of Technology</option><option>Northfield University</option><option>Coastal Research Center</option><option>Summit Polytechnic</option></select>
        <div className="input-row"><input className="input" placeholder="Your name" defaultValue="Priya Nair" /><input className="input" placeholder="Password" type="password" defaultValue="network-access" /></div>
        <button className="primary-btn wide" onClick={signIn}><LockKeyhole size={15} /> Enter workspace <ArrowUpRight size={15} /></button>
        <div className="login-foot"><span><CheckCircle2 size={13} /> Demo access enabled</span><span>Any credentials work</span></div>
      </div>
    </main>
  </div>;

  return <div className="shell app-shell"><style>{css}</style>
    <header className="topbar"><div className="brand"><span className="brand-icon"><Radio size={18} /></span><span>LABRESOURCE <b>NETWORK</b></span></div><div className="topbar-center"><span className="live-pulse" /> NETWORK LIVE <span className="topbar-divider" /> Riverside Institute of Technology</div><div className="topbar-actions"><button className="icon-btn" title="Refresh status" onClick={() => setNotice("Network status refreshed just now")}><RefreshCw size={16} /></button><button className="icon-btn notification-btn" title="Notifications" onClick={() => setNotice("3 availability notifications · 1 approval needs review")}><Bell size={17} /><i /></button><button className="user-menu" onClick={() => setSignedIn(false)}><span className="avatar">PN</span><span><b>Priya Nair</b><small>{activeRole.short}</small></span><LogOut size={14} /></button></div></header>
    <div className="mobile-rolebar"><Menu size={17} /> Role view <select value={role} onChange={(e) => switchRole(e.target.value as RoleId)}>{roles.map((item) => <option value={item.id} key={item.id}>{item.label}</option>)}</select></div>
    <div className="app-body"><aside className="sidebar"><div className="workspace-label">CURRENT WORKSPACE</div><div className="active-role"><span className="active-role-icon"><RoleIcon size={18} /></span><span><b>{activeRole.short}</b><small>Riverside · scoped access</small></span></div><div className="workspace-label nav-label">YOUR DECISIONS</div><nav>{tabs.map((item) => { const Icon = item.icon; return <button key={item.id} className={tab === item.id ? "nav-active" : ""} onClick={() => { setTab(item.id); setConflict(false); }}><Icon size={16} />{item.label}{item.id === "bookings" && <span className="nav-count">2</span>}</button>; })}</nav><div className="sidebar-bottom"><div className="workspace-label">INSPECT A ROLE</div><select className="role-switch" value={role} onChange={(e) => switchRole(e.target.value as RoleId)}>{roles.map((item) => <option value={item.id} key={item.id}>{item.label}</option>)}</select><button className="signout" onClick={() => setSignedIn(false)}><LogOut size={14} /> Sign out</button></div></aside>
      <main className="main-content"><div className="content-head"><div><div className="breadcrumb">LABRESOURCE NETWORK <span>/</span> {activeRole.short.toUpperCase()}</div><h1>{tabTitle(role, tab)}</h1><p>{tabDescription(role, tab)}</p></div><div className="sync-note"><span className="sync-dot" />{notice}</div></div>
        {conflict && <div className="conflict-banner"><XCircle size={19} /><div><b>Double-booking prevented</b><span>TEM-2200 Electron Microscope is already reserved today from 13:30–15:30. Choose another window or join its waitlist.</span></div><button onClick={() => { setConflict(false); setTab("waitlist"); }}>View waitlist <ArrowUpRight size={14} /></button></div>}
        {tab === "overview" && <Overview role={role} requests={requests} onTab={setTab} onDecide={decide} />}
        {tab === "availability" && <Availability instruments={filteredInstruments} query={query} setQuery={setQuery} onBook={requestBooking} waitlisted={waitlisted} onWait={(name) => { setWaitlisted((items) => items.includes(name) ? items : [...items, name]); setNotice(`${name} added to your waitlist`); }} />}
        {tab === "bookings" && <Bookings role={role} requests={requests} onDecide={decide} onBook={requestBooking} />}
        {tab === "waitlist" && <Waitlist waitlisted={waitlisted} onWait={(name) => { setWaitlisted((items) => items.includes(name) ? items : [...items, name]); setNotice(`${name} added to your waitlist`); }} />}
        {tab === "operations" && <Operations />}
        {tab === "sharing" && <Sharing requests={requests} onDecide={decide} />}
        {tab === "analytics" && <Analytics institution={role === "institution"} />}
        {tab === "system" && <SystemOverview />}
      </main>
    </div>
  </div>;
}

function tabTitle(role: RoleId, tab: TabId) { if (tab === "overview") return role === "researcher" ? "Your research queue" : role === "technician" ? "Operations at a glance" : role === "institution" ? "Institution pulse" : role === "system" ? "System control room" : "Decisions that move the lab"; return ({ availability: "Find available equipment", bookings: role === "manager" ? "Booking approvals" : "Your bookings", waitlist: role === "manager" ? "Waitlist optimization" : "My waitlist", operations: role === "technician" ? "Live equipment status" : "Live status", sharing: role === "institution" ? "Partner network visibility" : "Sharing & approvals", analytics: role === "institution" ? "Organization-wide analytics" : "Utilization & demand", system: "Configuration & audit" } as Record<string, string>)[tab] || "Workspace"; }
function tabDescription(role: RoleId, tab: TabId) { if (tab === "overview") return role === "researcher" ? "A concise view of reservations, availability, and your waitlist." : "Real-time signals, prioritized actions, and the context behind them."; return tab === "availability" ? "Search the shared network, compare windows, and request access without guesswork." : tab === "analytics" ? "Demand signals turn instrument activity into your next allocation decision." : "The tools and decisions owned by your role, kept in one focused view."; }

function Overview({ role, requests, onTab, onDecide }: { role: RoleId; requests: typeof initialRequests; onTab: (tab: TabId) => void; onDecide: (id: number, status: "Approved" | "Rejected") => void }) {
  if (role === "researcher") return <><div className="metrics"><Metric label="UPCOMING BOOKINGS" value="02" hint="Next: TEM-2200 · today 14:00" /><Metric label="AVAILABLE NOW" value="09" hint="Across 4 institutions" accent="blue" /><Metric label="WAITLIST POSITION" value="#02" hint="Mass Spectrometer M-4" accent="amber" /></div><div className="grid-two"><Panel title="Next on your bench" eyebrow="TODAY"><div className="booking-focus"><div className="instrument-glyph"><Microscope size={25} /></div><div><b>TEM-2200 Electron Microscope</b><span>14:00–16:00 · Bay 04 · Riverside Institute</span></div><StatusChip status="Approved" /></div><button className="text-btn" onClick={() => onTab("bookings")}>Open booking details <ArrowUpRight size={14} /></button></Panel><Panel title="Availability notifications" eyebrow="ALERTS" action={<span className="small-count">3 new</span>}><Notification text="SEM-500 Scanning Microscope is available for 2h." time="8 min ago" /><Notification text="Your M-4 waitlist position moved to #2." time="1h ago" /><Notification text="Northfield approved partner access." time="Yesterday" /></Panel></div></>;
  if (role === "technician") return <><div className="metrics"><Metric label="LIVE INSTRUMENTS" value="14" hint="11 healthy · 2 in use" /><Metric label="MAINTENANCE FLAGS" value="02" hint="1 needs attention" accent="red" /><Metric label="CHECKS DUE" value="04" hint="Next check in 26 min" accent="amber" /></div><div className="grid-two"><Panel title="Priority operations" eyebrow="NEEDS ATTENTION"><OperationRow name="Beckman Coulter Centrifuge" note="Vacuum seal inspection" status="Maintenance" /><OperationRow name="TEM-2200 Electron Microscope" note="Calibration check due · 26 min" status="Available" /><OperationRow name="HPLC Chromatography Rig" note="Status not reported · 47 min" status="In Use" /></Panel><Panel title="Technician scope" eyebrow="ROLE BOUNDARY"><div className="scope-copy"><Wrench size={22} /><b>Keep the network truthful.</b><p>Update live state, log maintenance, and complete operational checks. Booking approvals and utilization decisions stay with the Lab Manager.</p><button className="secondary-btn" onClick={() => onTab("operations")}>Open live status <ArrowRightIcon /></button></div></Panel></div></>;
  if (role === "institution") return <><div className="metrics"><Metric label="NETWORK UTILIZATION" value="68.4%" hint="+4.8 pts vs last month" /><Metric label="PARTNER INSTITUTIONS" value="04" hint="12 active agreements" accent="blue" /><Metric label="SHARING REQUESTS" value="03" hint="2 awaiting approval" accent="amber" /></div><div className="grid-two"><Panel title="Network health" eyebrow="ORGANIZATION VIEW"><BarList items={[["Riverside Institute of Technology", 78], ["Northfield University", 71], ["Coastal Research Center", 56], ["Summit Polytechnic", 48]]} /></Panel><Panel title="Approvals in your lane" eyebrow="PARTNER ACCESS"><RequestRow text="Northfield University → TEM-2200" meta="External access · received 24 min ago" status="Pending" /><button className="text-btn" onClick={() => onTab("sharing")}>Review partner requests <ArrowUpRight size={14} /></button></Panel></div></>;
  if (role === "system") return <><div className="metrics"><Metric label="NETWORK HEALTH" value="99.8%" hint="All core services operational" /><Metric label="ACTIVE USERS" value="184" hint="Across 4 institutions" accent="blue" /><Metric label="AUDIT EVENTS" value="27" hint="Last 24 hours" accent="amber" /></div><div className="grid-two"><Panel title="Coverage by role" eyebrow="ACCESS MODEL"><RoleCoverage label="Researchers / Students" value="126 users" width="76%" /><RoleCoverage label="Lab Technicians" value="24 users" width="38%" /><RoleCoverage label="Managers & Heads" value="18 users" width="28%" /><RoleCoverage label="Institution & System Admins" value="16 users" width="24%" /></Panel><Panel title="System status" eyebrow="LAST 24 HOURS"><SystemRow icon={<Database size={16} />} label="Booking service" value="Operational" /><SystemRow icon={<ShieldCheck size={16} />} label="Permission sync" value="Healthy" /><SystemRow icon={<HardDrive size={16} />} label="Audit retention" value="92 days remaining" /></Panel></div></>;
  return <><div className="metrics"><Metric label="NETWORK UTILIZATION" value="68.4%" hint="+4.8 pts this week" /><Metric label="PENDING DECISIONS" value="05" hint="2 bookings · 3 sharing" accent="amber" /><Metric label="IDLE EQUIPMENT" value="03" hint="Over 3h threshold" accent="red" /></div><div className="grid-two"><Panel title="The decisions waiting for you" eyebrow="MANAGER QUEUE"><RequestRow text="Priya Nair · TEM-2200" meta="Booking · Today 14:00–16:00" status="Pending" actions={<><button className="approve-btn" onClick={() => onDecide(1, "Approved")}><Check size={14} /> Approve</button><button className="reject-btn" onClick={() => onDecide(1, "Rejected")}><X size={14} /> Reject</button></>} /><RequestRow text="Mateo Ruiz · Mass Spectrometer M-4" meta="Booking · Tomorrow 09:30–11:00" status="Pending" actions={<><button className="approve-btn" onClick={() => onDecide(2, "Approved")}><Check size={14} /> Approve</button><button className="reject-btn" onClick={() => onDecide(2, "Rejected")}><X size={14} /> Reject</button></>} /><button className="text-btn" onClick={() => onTab("bookings")}>View all booking requests <ArrowUpRight size={14} /></button></Panel><Panel title="Utilization signal" eyebrow="THIS WEEK"><div className="big-stat"><span>68.4%</span><div className="sparkline"><i /><i /><i /><i /><i /><i /><i /></div><small>+4.8 percentage points · highest since April</small></div><div className="signal-callout"><AlertTriangle size={16} /><span><b>Mass Spectrometer M-4</b> is at 91% utilization with 22 requests. Consider expanding evening access.</span></div></Panel></div></>;
}

function Availability({ instruments, query, setQuery, onBook, waitlisted, onWait }: { instruments: Instrument[]; query: string; setQuery: (v: string) => void; onBook: (name: string) => void; waitlisted: string[]; onWait: (name: string) => void }) { return <><div className="search-row"><div className="search-box"><Search size={16} /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search equipment or category" /></div><button className="secondary-btn"><SlidersHorizontal size={15} /> Filters</button><span className="results-count">{instruments.length} instruments in network</span></div><div className="instrument-list">{instruments.map((item) => <div className="instrument-row" key={item.name}><div className="instrument-icon"><FlaskConical size={19} /></div><div className="instrument-name"><b>{item.name}</b><span>{item.type} · {item.site}</span></div><div className="instrument-detail"><StatusChip status={item.status} /><small>{item.detail}</small></div><div className="instrument-actions">{item.status === "Available" ? <button className="primary-btn compact" onClick={() => onBook(item.name)}>Request time <ArrowUpRight size={14} /></button> : <button className={`secondary-btn compact ${waitlisted.includes(item.name) ? "waitlisted" : ""}`} onClick={() => onWait(item.name)}>{waitlisted.includes(item.name) ? <Check size={14} /> : <Timer size={14} />} {waitlisted.includes(item.name) ? "On waitlist" : "Join waitlist"}</button>}</div></div>)}</div></>; }

function Bookings({ role, requests, onDecide, onBook }: { role: RoleId; requests: typeof initialRequests; onDecide: (id: number, status: "Approved" | "Rejected") => void; onBook: (name: string) => void }) { return <Panel title={role === "manager" ? "Incoming booking requests" : "Reservations tied to your work"} eyebrow={role === "manager" ? "MANAGER ACTIONS" : "RESEARCHER VIEW"} action={<button className="secondary-btn compact"><CalendarDays size={14} /> Calendar</button>}><div className="table-head"><span>REQUESTER</span><span>INSTRUMENT</span><span>WINDOW</span><span>STATUS</span><span /></div>{requests.map((item) => <div className="table-row" key={item.id}><div><b>{item.person}</b><small>{item.institution}</small></div><div>{item.instrument}</div><div>{item.window}</div><div><StatusChip status={item.status} /></div><div className="row-actions">{role === "manager" && item.status === "Pending" ? <><button className="approve-btn" onClick={() => onDecide(item.id, "Approved")}><Check size={14} /> Approve</button><button className="reject-btn" onClick={() => onDecide(item.id, "Rejected")}><X size={14} /></button></> : <button className="text-btn" onClick={() => onBook(item.instrument)}>Details <ArrowUpRight size={13} /></button>}</div></div>)}</Panel>; }

function Waitlist({ waitlisted, onWait }: { waitlisted: string[]; onWait: (name: string) => void }) { const items = waitlisted.length ? waitlisted : ["Mass Spectrometer M-4"]; return <><div className="metrics"><Metric label="MY WAITLISTS" value={String(items.length).padStart(2, "0")} hint="Availability alerts on" /><Metric label="NEXT POSITION" value="#02" hint="Mass Spectrometer M-4" accent="amber" /><Metric label="NOTIFICATIONS" value="03" hint="Last alert 8 min ago" accent="blue" /></div><Panel title="Your waitlist" eyebrow="QUEUE + AVAILABILITY NOTIFICATIONS" action={<span className="live-tag"><span className="live-pulse" /> Alerts active</span>}>{items.map((name, index) => <div className="wait-row" key={name}><div className="wait-number">0{index + 1}</div><div><b>{name}</b><span>Riverside Institute of Technology · Joined today</span></div><div className="wait-position">Position <b>#{index + 2}</b></div><StatusChip status={index === 0 ? "Waiting" : "Pending"} /></div>)}<div className="empty-add"><Bell size={17} /><span>Get a notification the moment an opening appears.</span><button className="text-btn" onClick={() => onWait("SEM-500 Scanning Microscope")}>Add another <ArrowUpRight size={14} /></button></div></Panel></>; }

function Operations() { return <Panel title="Live equipment status" eyebrow="OPERATIONAL SUPPORT · UPDATED JUST NOW" action={<button className="secondary-btn compact"><RefreshCw size={14} /> Refresh</button>}><div className="table-head"><span>EQUIPMENT</span><span>STATUS</span><span>DURATION</span><span>MAINTENANCE</span><span>ACTION</span></div>{instruments.map((item, index) => <div className="table-row ops-row" key={item.name}><div><b>{item.name}</b><small>{item.site}</small></div><div><StatusChip status={item.status} /></div><div><Clock3 size={13} /> {index % 2 ? "1h 42m" : "3h 18m"}</div><div>{item.status === "Maintenance" ? <span className="flag flag-red"><AlertTriangle size={13} /> Inspection open</span> : <span className="flag"><CheckCircle2 size={13} /> No flag</span>}</div><button className="text-btn">Log check <ArrowUpRight size={13} /></button></div>)}</Panel>; }

function Sharing({ requests, onDecide }: { requests: typeof initialRequests; onDecide: (id: number, status: "Approved" | "Rejected") => void }) { return <div className="grid-two"><Panel title="Incoming sharing requests" eyebrow="OWNED BY LAB MANAGER / ADMIN"><RequestRow text="Northfield University → TEM-2200" meta="Requested by Dr. Leah Wong · 2-hour window" status="Pending" actions={<><button className="approve-btn" onClick={() => onDecide(2, "Approved")}><Check size={14} /> Approve</button><button className="reject-btn" onClick={() => onDecide(2, "Rejected")}><X size={14} /> Reject</button></>} /><RequestRow text="Summit Polytechnic → Thermal Cycler PCR-8" meta="Requested by Omar Shah · recurring access" status="Pending" actions={<><button className="approve-btn" onClick={() => onDecide(3, "Approved")}><Check size={14} /> Approve</button><button className="reject-btn" onClick={() => onDecide(3, "Rejected")}><X size={14} /> Reject</button></>} /></Panel><Panel title="Active partner agreements" eyebrow="NETWORK VISIBILITY"><Partner name="Northfield University" detail="4 instruments · 12 active reservations" /><Partner name="Coastal Research Center" detail="2 instruments · access review in 18 days" /><Partner name="Summit Polytechnic" detail="3 instruments · 8 active reservations" /></Panel></div>; }

function Analytics({ institution }: { institution: boolean }) { const heat = [42, 68, 84, 73, 91, 55, 36]; return <><div className="metrics"><Metric label={institution ? "ORG-WIDE UTILIZATION" : "LAB UTILIZATION"} value={institution ? "68.4%" : "74.8%"} hint="+4.8 pts over prior period" /><Metric label="IDLE EQUIPMENT" value="03" hint="Over 3h idle threshold" accent="red" /><Metric label="HIGH-DEMAND QUEUE" value="06" hint="Requires allocation review" accent="amber" /></div><div className="grid-two"><Panel title="Utilization heatmap" eyebrow="MON–SUN · LOW / MEDIUM / HIGH"><div className="heatmap-legend"><span><i className="low" /> Low</span><span><i className="medium" /> Medium</span><span><i className="high" /> High</span></div><div className="heatmap">{["TEM-2200", "Ultra Centrifuge X9", "Mass Spectrometer M-4", "SEM-500", "PCR System"].map((name, row) => <div className="heat-row" key={name}><small>{name}</small>{heat.map((base, day) => <i key={day} className={base + row * 7 > 76 ? "high" : base + row * 7 > 48 ? "medium" : "low"} style={{ opacity: .55 + ((base + row * 7) % 35) / 100 }} />)}</div>)}</div><div className="days"><span>Mon</span><span>Tue</span><span>Wed</span><span>Thu</span><span>Fri</span><span>Sat</span><span>Sun</span></div></Panel><Panel title="High-demand equipment" eyebrow="REQUESTS + RESERVATIONS"><Demand name="Mass Spectrometer M-4" requests="22 requests" pct="91%" /><Demand name="TEM-2200 Electron Microscope" requests="18 requests" pct="84%" /><Demand name="Ultra Centrifuge X9" requests="15 requests" pct="72%" /><div className="idle-box"><Timer size={16} /><span><b>Idle duration watch</b><small>SEM-500 · 4h 12m idle<br />Real-Time PCR · 5h 06m idle</small></span></div></Panel></div></>; }

function SystemOverview() { return <div className="grid-two"><Panel title="Configuration & audit" eyebrow="SYSTEM ADMIN ONLY"><SystemRow icon={<Users size={16} />} label="Role coverage" value="5 role models active" /><SystemRow icon={<SlidersHorizontal size={16} />} label="Booking policy" value="Manager approval required" /><SystemRow icon={<Network size={16} />} label="Partner trust links" value="12 active" /><SystemRow icon={<ShieldCheck size={16} />} label="Last permission review" value="Today · 08:42" /></Panel><Panel title="Recent audit events" eyebrow="TRACEABLE BY DEFAULT"><SystemRow icon={<CheckCircle2 size={16} />} label="Access request approved" value="Northfield · 4m ago" /><SystemRow icon={<AlertTriangle size={16} />} label="Maintenance flag opened" value="Beckman · 21m ago" /><SystemRow icon={<LockKeyhole size={16} />} label="Role scope updated" value="Riverside · 1h ago" /></Panel></div>; }

function Notification({ text, time }: { text: string; time: string }) { return <div className="notification"><span className="notification-icon"><Bell size={14} /></span><span><b>{text}</b><small>{time}</small></span></div>; }
function RequestRow({ text, meta, status, actions }: { text: string; meta: string; status: string; actions?: React.ReactNode }) { return <div className="request-row"><div><b>{text}</b><span>{meta}</span></div><StatusChip status={status} />{actions && <div className="request-actions">{actions}</div>}</div>; }
function OperationRow({ name, note, status }: { name: string; note: string; status: string }) { return <div className="operation-row"><span className="operation-icon"><Activity size={15} /></span><span><b>{name}</b><small>{note}</small></span><StatusChip status={status} /></div>; }
function BarList({ items }: { items: [string, number][] }) { return <div className="bar-list">{items.map(([name, value]) => <div key={name}><div><b>{name}</b><span>{value}%</span></div><div className="bar-track"><i style={{ width: `${value}%` }} /></div></div>)}</div>; }
function RoleCoverage({ label, value, width }: { label: string; value: string; width: string }) { return <div className="coverage"><div><b>{label}</b><span>{value}</span></div><div className="bar-track"><i style={{ width }} /></div></div>; }
function SystemRow({ icon, label, value }: { icon: React.ReactNode; label: string; value: string }) { return <div className="system-row"><span className="system-icon">{icon}</span><b>{label}</b><span>{value}</span></div>; }
function Partner({ name, detail }: { name: string; detail: string }) { return <div className="partner"><span className="partner-icon"><Network size={16} /></span><span><b>{name}</b><small>{detail}</small></span><CheckCircle2 size={16} className="partner-ok" /></div>; }
function Demand({ name, requests, pct }: { name: string; requests: string; pct: string }) { return <div className="demand"><span><b>{name}</b><small>{requests}</small></span><strong>{pct}</strong></div>; }
function ArrowRightIcon() { return <ArrowUpRight size={14} />; }

